const body = $json.body ?? {};

const allowedEventTypes = new Set([
  "signup_completed",
  "workspace_created",
  "core_workflow_created",
  "core_workflow_executed",
  "teammate_invited",
  "integration_connected",
  "usage_threshold_reached",
  "upgrade_intent_detected"
]);

const workspaceRequiredEvents = new Set([
  "workspace_created",
  "core_workflow_created",
  "core_workflow_executed",
  "teammate_invited",
  "integration_connected",
  "usage_threshold_reached",
  "upgrade_intent_detected"
]);

const errors = [];

const eventId =
  typeof body.event_id === "string"
    ? body.event_id.trim()
    : "";

const eventType =
  typeof body.event_type === "string"
    ? body.event_type.trim().toLowerCase()
    : "";

const productUserId =
  typeof body.product_user_id === "string"
    ? body.product_user_id.trim()
    : "";

const workspaceId =
  typeof body.workspace_id === "string"
    ? body.workspace_id.trim()
    : null;

const email =
  typeof body.email === "string"
    ? body.email.trim().toLowerCase()
    : null;

if (!eventId) {
  errors.push("event_id is required");
}

if (!eventType) {
  errors.push("event_type is required");
} else if (!allowedEventTypes.has(eventType)) {
  errors.push(`unsupported event_type: ${eventType}`);
}

if (!productUserId) {
  errors.push("product_user_id is required");
}

if (
  workspaceRequiredEvents.has(eventType) &&
  !workspaceId
) {
  errors.push(
    `workspace_id is required for ${eventType}`
  );
}

let occurredAt = null;

if (!body.occurred_at) {
  errors.push("occurred_at is required");
} else {
  const parsedDate = new Date(body.occurred_at);

  if (Number.isNaN(parsedDate.getTime())) {
    errors.push("occurred_at must be a valid timestamp");
  } else {
    occurredAt = parsedDate.toISOString();
  }
}

let eventProperties = {};

if (body.properties !== undefined) {
  if (
    body.properties === null ||
    typeof body.properties !== "object" ||
    Array.isArray(body.properties)
  ) {
    errors.push("properties must be a JSON object");
  } else {
    eventProperties = body.properties;
  }
}

return {
  json: {
    validation_status:
      errors.length === 0 ? "valid" : "invalid",

    validation_errors: errors,

    event_id: eventId || null,
    event_type: eventType || null,
    occurred_at: occurredAt,
    product_user_id: productUserId || null,
    workspace_id: workspaceId,
    email: email,

    event_properties: eventProperties,

    received_at: new Date().toISOString()
  }
};

const total = $json.total ?? 0;
const results = $json.results ?? [];

let lookup_status;

if (total === 1) {
  lookup_status = "resolved";
} else if (total === 0) {
  lookup_status = "not_found";
} else {
  lookup_status = "ambiguous";
}

return {
  json: {
    lookup_status,
    match_count: total,
    hubspot_contact_id: total === 1 ? results[0].id : null,
    matched_contact: total === 1 ? results[0].properties : null
  }
};

const signals = $input.all();

const model = {
  signup_completed: {
    points: 5,
    cap: 1
  },
  workspace_created: {
    points: 10,
    cap: 1
  },
  core_workflow_created: {
    points: 15,
    cap: 3
  },
  core_workflow_executed: {
    points: 10,
    cap: 3
  },
  teammate_invited: {
    points: 15,
    cap: 2
  },
  integration_connected: {
    points: 30,
    cap: 2
  },
  usage_threshold_reached: {
    points: 35,
    cap: 1
  },
  upgrade_intent_detected: {
    points: 50,
    cap: 1
  }
};

let score = 0;
let commercialIntentDetected = false;
const breakdown = [];

for (const item of signals) {
  const eventType = item.json.event_type;
  const rawCount = Number(item.json.event_count || 0);

  const rule = model[eventType];

  if (!rule) {
    continue;
  }

  const countedEvents = Math.min(rawCount, rule.cap);
  const contribution = countedEvents * rule.points;

  score += contribution;

  if (eventType === 'upgrade_intent_detected' && rawCount > 0) {
    commercialIntentDetected = true;
  }

  breakdown.push({
    event_type: eventType,
    raw_count: rawCount,
    counted_events: countedEvents,
    points_each: rule.points,
    contribution
  });
}

let intentState;

if (commercialIntentDetected) {
  intentState = 'commercial_intent';
} else if (score >= 70) {
  intentState = 'high_intent';
} else if (score >= 30) {
  intentState = 'medium_intent';
} else {
  intentState = 'low_intent';
}

return [
  {
    json: {
      rolling_intent_score: score,
      rolling_intent_state: intentState,
      commercial_intent_detected: commercialIntentDetected,
      scoring_window_days: 30,
      model_version: 'v1',
      signal_breakdown: breakdown
    }
  }
];

const props = $json.properties ?? {};

const country = (props.country ?? '').trim();
const industry = (props.industry ?? '').trim();
const employees = Number(props.numberofemployees ?? 0);

let fit = 'weak_fit';
const reasons = [];

// Geography
const supportedCountries = [
  'Germany',
  'United States',
  'Canada',
  'United Kingdom',
  'France',
  'Netherlands'
];

const geographyFit = supportedCountries.includes(country);

if (geographyFit) {
  reasons.push(`Supported geography: ${country}`);
} else {
  reasons.push(`Unsupported or unknown geography: ${country || 'missing'}`);
}

// Company size
let sizeFit = 'weak';

if (employees >= 50 && employees < 250) {
  sizeFit = 'strong';
  reasons.push(`Strong company-size fit: ${employees} employees`);
} else if (employees >= 20 && employees < 1000) {
  sizeFit = 'moderate';
  reasons.push(`Moderate company-size fit: ${employees} employees`);
} else if (employees >= 1000) {
  sizeFit = 'enterprise';
  reasons.push(`Enterprise account: ${employees} employees`);
} else {
  reasons.push(`Weak or unknown company-size fit: ${employees || 'missing'}`);
}

// Industry
const targetIndustries = [
  'INFORMATION_TECHNOLOGY_AND_SERVICES',
  'COMPUTER_SOFTWARE',
  'INTERNET'
];

const industryFit = targetIndustries.includes(industry);

if (industryFit) {
  reasons.push(`Target industry: ${industry}`);
} else {
  reasons.push(`Non-target or unknown industry: ${industry || 'missing'}`);
}

// Final fit
if (!geographyFit) {
  fit = 'disqualified';
} else if (sizeFit === 'enterprise') {
  fit = 'moderate_fit';
} else if (sizeFit === 'strong' && industryFit) {
  fit = 'strong_fit';
} else if (
  (sizeFit === 'strong' || sizeFit === 'moderate') &&
  industryFit
) {
  fit = 'moderate_fit';
} else {
  fit = 'weak_fit';
}

return {
  json: {
    hubspot_company_id: $json.id,
    workspace_id: props.workspace_id,
    company_name: props.name,
    country,
    industry,
    number_of_employees: employees,
    icp_fit: fit,
    icp_fit_reasons: reasons
  }
};

const identity = $('Identity Resolved?').item.json;
const company = $json;

const missing = [];

if (!identity.product_user_id) {
  missing.push('product_user_id');
}

if (!identity.workspace_id) {
  missing.push('workspace_id');
}

if (!identity.hubspot_contact_id) {
  missing.push('hubspot_contact_id');
}

if (!identity.hubspot_company_id) {
  missing.push('hubspot_company_id');
}

if (!company.company_name) {
  missing.push('company_name');
}

if (!company.country) {
  missing.push('country');
}

if (!company.industry) {
  missing.push('industry');
}

if (!company.number_of_employees) {
  missing.push('number_of_employees');
}

let dataReadiness;

if (missing.length === 0) {
  dataReadiness = 'ready';
} else {
  dataReadiness = 'incomplete';
}

return {
  json: {
    ...company,
    data_readiness: dataReadiness,
    missing_fields: missing,
    hubspot_contact_id: identity.hubspot_contact_id,
    hubspot_company_id: identity.hubspot_company_id,
    product_user_id: identity.product_user_id
  }
};

const data = $json;

const signalState = $('Persist Rolling Intent State').item.json;

const icpFit = data.icp_fit;
const dataReadiness = data.data_readiness;
const intentState = signalState.product_intent_state;
const intentScore = Number(signalState.product_intent_score ?? 0);
const commercialIntent = signalState.commercial_intent_detected === true;

let qualificationState = 'monitoring';
let qualificationReason = [];

// Hard readiness blocker
if (dataReadiness !== 'ready') {
  qualificationState = 'handoff_blocked';
  qualificationReason.push(`Data readiness is ${dataReadiness}`);
}

// Commercial disqualification
else if (icpFit === 'disqualified') {
  qualificationState = 'not_qualified';
  qualificationReason.push('Account failed ICP requirements');
}

// Strong signal + acceptable fit
else if (
  (icpFit === 'strong_fit' || icpFit === 'moderate_fit') &&
  (intentState === 'high_intent' || commercialIntent)
) {
  qualificationState = 'sales_ready';
  qualificationReason.push(
    `${icpFit} with ${intentState} product intent`
  );
}

// Promising but not yet sales-ready
else if (
  (icpFit === 'strong_fit' || icpFit === 'moderate_fit') &&
  intentState === 'medium_intent'
) {
  qualificationState = 'pql_candidate';
  qualificationReason.push(
    `${icpFit} with medium product intent`
  );
}

// Weak fit requires review if intent is strong
else if (
  icpFit === 'weak_fit' &&
  (intentState === 'high_intent' || commercialIntent)
) {
  qualificationState = 'needs_review';
  qualificationReason.push(
    `Strong product intent but weak ICP fit`
  );
}

else {
  qualificationState = 'monitoring';
  qualificationReason.push(
    `Current fit and intent combination does not meet qualification threshold`
  );
}

return {
  json: {
    ...data,
    product_intent_score: intentScore,
    product_intent_state: intentState,
    commercial_intent_detected: commercialIntent,
    qualification_state: qualificationState,
    qualification_reason: qualificationReason.join('; ')
  }
};

