const qualification = $('Calculate Qualification Decision').item.json;

const country = qualification.country;
const employees = Number(qualification.number_of_employees ?? 0);
const qualificationState = qualification.qualification_state;

let routingTarget = 'manual_review';
let routingReason = [];

const northAmerica = [
  'United States',
  'Canada'
];

const emea = [
  'Germany',
  'United Kingdom',
  'France',
  'Netherlands'
];

if (qualificationState !== 'sales_ready') {
  routingTarget = 'manual_review';
  routingReason.push(`Qualification state is ${qualificationState}`);
}

else if (employees >= 1000) {
  routingTarget = 'enterprise_review';
  routingReason.push(`Enterprise account with ${employees} employees`);
}

else if (northAmerica.includes(country) && employees < 100) {
  routingTarget = 'na_smb';
  routingReason.push(`${country}, ${employees} employees`);
}

else if (northAmerica.includes(country) && employees >= 100) {
  routingTarget = 'na_mid_market';
  routingReason.push(`${country}, ${employees} employees`);
}

else if (emea.includes(country) && employees < 100) {
  routingTarget = 'emea_smb';
  routingReason.push(`${country}, ${employees} employees`);
}

else if (emea.includes(country) && employees >= 100) {
  routingTarget = 'emea_mid_market';
  routingReason.push(`${country}, ${employees} employees`);
}

else {
  routingTarget = 'manual_review';
  routingReason.push(`No deterministic routing rule for ${country || 'unknown geography'}`);
}

return {
  json: {
    ...qualification,
    routing_target: routingTarget,
    routing_reason: routingReason.join('; ')
  }
};

